function bankTaught(FL, bankId, heard) {
  const b = FL.quiz.BANKS.find(x => x.id === bankId), m = BANK_ANSWERS[bankId];
  if (!b || !m) return 0;
  return b.qs.filter((_, k) => m[k] && m[k].a && allHeard(m[k].a, heard)).length;
}

